parameters.jsCode:
// Get the input data from previous nodes
const dealAmount = $('AI Input Payload').first().json.dealAmount;
const currentStage = $('AI Input Payload').first().json.currentStage;
const competitorName = $('AI Input Payload').first().json.competitorName;
const accountHistory = $('Account History Summary').first().json.summary || "";

// Initialize scoring variables
let riskScore = 50; // Start at neutral 50

// Adjust based on deal size (larger deals = higher risk)
if (dealAmount > 1000000) {
  riskScore += 15;
} else if (dealAmount > 750000) {
  riskScore += 10;
}

// Adjust based on sales stage (later stages = lower risk if we're still in)
if (currentStage === "Proposal" || currentStage === "Negotiation") {
  riskScore -= 10;
} else if (currentStage === "Qualification") {
  riskScore += 5;
}

// Adjust based on competitor strength
const toughCompetitors = ["Salesforce", "Oracle", "Microsoft Dynamics"];
if (toughCompetitors.includes(competitorName)) {
  riskScore += 15;
}

// Check account history for wins
if (accountHistory.includes("IsWon = true")) {
  riskScore -= 20; // Existing customer relationship reduces risk
}

// Determine risk level category
let riskLevel;
if (riskScore >= 70) {
  riskLevel = "HIGH RISK";
} else if (riskScore >= 50) {
  riskLevel = "MODERATE RISK";
} else {
  riskLevel = "LOW RISK";
}

// Return the enhanced data
return {
  ...$input.first().json,
  competitiveRiskScore: riskScore,
  riskLevel: riskLevel,
  requiresExecutiveReview: riskScore >= 70
};

