  const opps = $('Account Opportunities').first().json.data;
  const wins = opps.filter(o => o.IsWon === true).length;
  const losses = opps.filter(o => o.IsWon === false).length;
  const open = opps.filter(o => o.IsWon === null).length;
  const totalValue = opps.reduce((sum, o) => sum + (o.Amount || 0), 0);

  let summary = `Account History Summary:\n`;
  summary += `Total Past Opportunities: ${opps.length}\n`;
  summary += `Wins: ${wins} | Losses: ${losses} | Currently Open: ${open}\n`;
  summary += `Total Historical Value: $${totalValue.toLocaleString()}\n\n`;
  summary += `Recent Opportunities:\n`;
  summary += opps.slice(0, 5).map(opp => {
    const status = opp.IsWon === true ? 'WON' : (opp.IsWon === false ? 'LOST' : 'OPEN');
    return `- ${opp.Name}: $${(opp.Amount || 0).toLocaleString()} - ${status} (${opp.CloseDate})`;
  }).join('\n');


return {
  json:{
    summary
  }
};
